TexNorm = vec3(TexNorm.x, TexNorm.y, z);// Putting it all together for a proper vector. (-1 to 1 ranged)
TexNorm = normalize(TexNorm);
vec3 DspNorm = (TexNorm + 1.0)*0.5;//  normal map, ranged for monitor display
// Camera -- Get the vector to the camera relative to the current pixel in pixels,
//  so as to give the aproximate location of the viewers head.
vec3 vecToCam = vec3(0.5 * q10, 0.50 * q11, 1.15 * q10);//Where's your head at in screen coordinate space?
vecToCam = vecToCam - vecToTex;//vector fom texel to your head in pixels
vecToCam = normalize(vecToCam);
// Point Light--Get the Point Light vector and color data, then use data to get point light color.
vec3 vecToPtL = vec3(q1,q2,q3);//provided in per uFrame
vecToPtL = vecToPtL - vecToTex;//make vector relative to this texel
float vTPLLength = sqrt(pow(vecToPtL.x, 2.0 )+pow(vecToPtL.y, 2.0 )+pow(vecToPtL.z, 2.0 ));
vecToPtL = normalize(vecToPtL);//normalize
vec3 PtLColor = texture(sampler_fw_ColorLUT, vec2(q4, 0.5)).xyz;//use ColorLUT
// Environment Light--Using q6 = phi & q7 = theta to get the vector to the Environmental Light
z = sin(q7);  float n = cos(q7);  float y = sin(q6) * n;  float x = cos(q6) * n;
vec3 vecToEnL = vec3(x,y,z);//calculate from phi & theta
vec3 EnLColor = texture(sampler_fw_ColorLUT, vec2(q8, q9)).xyz;//use ColorLUT
//=======================>>>>>>>>>>> Generate Lighting <<<<<<<<<<<<======================
//---------------------------------------------------------------------------------------
//***********TODO2: lay in material properties equations on both lights
// Generate the Environmental light contribution
float EnLAngularFactor = (TexHeight > 0.0) * min(max(dot(TexNorm,vecToEnL),0.002),1.0);
vec3 EnLContrib = pow(1.7 * EnLAngularFactor, 2.0 ) * EnLColor * TexColor;
// Generate Environmental light specular highlights
vec3 EnLSpecVec = vec3(250.0 * vecToEnL.x + vecToCam.x, 250.0 * vecToEnL.y + vecToCam.y, 250.0 * vecToEnL.z + vecToCam.z);
EnLSpecVec = normalize(EnLSpecVec);
float EnLSAngFact = max(0.0, dot(EnLSpecVec, TexNorm));
EnLSAngFact = pow((1.0 - sqrt(1.0 - pow(EnLSAngFact, 2.0 ))) * (TexHeight > 0.0), 1.0 + (hardness * 255.0));
EnLContrib = mix(EnLContrib, EnLColor, EnLSAngFact);
// Generate point light contribution
float PtLAngularFactor = (TexHeight > 0.0) * min(max(dot(TexNorm, vecToPtL),0.00),1.0);
float brightness = q5;//***********TODO4: rework point light falloff
float factor = (1.0 - brightness) * 0.01805;
float falloff = 0.01805 + max( 0.0 ,(1.0 - (vTPLLength * (0.000075 + factor))));//brightness of 1 = 0.00025 0 = 0.0183 gives a ranging factor of 0.01805
vec3 PtLContrib = (PtLAngularFactor * falloff) * PtLColor * TexColor;
// Generate point lights specular highlight
vec3 PtLSpecVec = vec3(vecToPtL.x + vecToCam.x, vecToPtL.y + vecToCam.y, vecToPtL.z + vecToCam.z);
PtLSpecVec = normalize(PtLSpecVec);
float PtLSAngFact = max(0.0, dot(PtLSpecVec, TexNorm));
PtLSAngFact = pow((1.0 - sqrt(1.0 - pow(PtLSAngFact, 2.0 ))) * (TexHeight > 0.0), 1.0 + (hardness * 255.0));
PtLContrib = mix(PtLContrib, min(PtLColor * q5, 1.0), PtLSAngFact);
ret = PtLContrib + EnLContrib;//PtLAngularFactor * falloff;//input;//EnLContrib;//DspNorm;//EnLAngularFactor;// distToPtL;// vec3(uv.x, uv.y, TexHeight);//
//ret = PtLSAngFact; //(1.0 + PtLSpecVec) * 0.5;
//  Dev Blog!!!
//  tracked the problem with the point light down to the interaction between the surface normal and the vector to point light
//  works just fine if I plug in the environmental light vector, so the prob is in the vector to point light, or one or more
//    of the components that go into it,
//  Probs need to remake both vectors measured in pixels not 0.0 to 1.0, then subtract those vectors and normalize.
//  That should give good values to the dot product function.
//  yup!! That float it.  now to lay in the point light's falloff.
//  K, PtL falloff working, next up is the specular reflections
//  Then the material properties, followed by the MaterialsLUT
//
//  Well, this is not going well...  seems to be some problem with vecToCam and/or the part where I add it to the vecToPtL
//    and normalize, may be some mismatch in the vector data, may be a dodgey normalize() function, I Don't Know.
//  I do Know that I am brain-fried though, so Imma play games now.
//
//  K, so got the specular working for both lights, and hardness is working.
//  Next up is Sub-Surface Scattering.
//  Oh yeah, the problem with my vector to cam seems to have been that pixelsx/y is not the same as uTexSize.xy
//    I suspect that one returns internal canvas size in pixels, while the other is monitor size in pixels.
//    I just put the pixelsx/y onto q10 & 11 to use them in the shader as needed.  It works.
//  Thinking I'm gonna need an object to test a lot of these material properties, so that I can manipulate
//    its material properties and location, for tranaparency, SSS and fresnel development.
//  Also need to split a couple of branches for lighting non-LUT pluggins, one on socks_12 and one on 8
//    will split them off once all material properties are functional except refractive index, which will be
//    dropped and transparency will be replaced with translucency, since transpareny won't work without
//    using a LUT to pull it off, among other things.
//  I'm cooked, more to come.
}
  fragColor = vec4(ret, 1.0);
}

